 const runContentMoat=async(e:FormEvent)=>{e.preventDefault();let competitors:unknown;try{competitors=JSON.parse(contentMoatCompetitorsJson)}catch{setLoadError("Enter valid JSON for the competitor observations.");return}if(!Array.isArray(competitors)||competitors.length<1||competitors.length>5){setLoadError("Supply a JSON array of one to five competitor objects.");return}const currentPages=Number(contentMoatCurrentPages);if(!Number.isInteger(currentPages)||currentPages<0||currentPages>100000){setLoadError("Current page count must be a whole number from 0 to 100000.");return}if(contentMoatNiche.trim().length<3){setLoadError("Enter a niche or topic to evaluate.");return}setBusy("Calculate content moat");setLoadError("");try{const data=await apiFetch<ContentMoatResult>("/api/research/content-moat",{method:"POST",body:JSON.stringify({niche:contentMoatNiche.trim(),hub_keyword:contentMoatKeyword.trim(),your_current_pages:currentPages,publishing_capacity:contentMoatCapacity,competitors})});setContentMoatResult(data);setResult({label:"Calculate content moat",data:{asset_id:data.asset_id,competitors_analyzed:data.competitors_analyzed,average_competitor_pages:data.average_competitor_pages,moat_target:data.moat_target,content_gap:data.content_gap,weeks_to_moat:data.weeks_to_moat,feasibility:data.feasibility},time:new Date().toISOString()})}catch(err){setLoadError(err instanceof Error?err.message:"Content moat calculation failed")}finally{setBusy("")}};
 const runContentDecay=async(e:FormEvent)=>{e.preventDefault();let pages:unknown;try{pages=JSON.parse(contentDecayPagesJson)}catch{setLoadError("Enter valid JSON for the supplied content-page observations.");return}if(!Array.isArray(pages)||pages.length<1||pages.length>30){setLoadError("Supply a JSON array of 1–30 content page objects.");return}if(!contentDecaySiteUrl.trim()){setLoadError("Provide your site's public base URL.");return}setBusy("Analyze content decay");setLoadError("");try{const data=await apiFetch<ContentDecayResult>("/api/research/content-decay",{method:"POST",body:JSON.stringify({site_url:contentDecaySiteUrl.trim(),timeframe:contentDecayTimeframe,pages})});setContentDecayResult(data);setResult({label:"Analyze content decay",data:{asset_id:data.asset_id,pages_analyzed:data.pages_analyzed,pages_decaying:data.pages_decaying,total_refresh_effort_hours:data.total_refresh_effort_hours,search_console_connected:data.search_console_connected,publishing_started:data.publishing_started},time:new Date().toISOString()})}catch(err){setLoadError(err instanceof Error?err.message:"Content decay analysis failed")}finally{setBusy("")}};
 const createCategoryDesign=async(e:FormEvent)=>{e.preventDefault();const niche=categoryNiche.trim();const target_audience=categoryAudience.trim();const topic_candidates=categoryTopicsText.split("\n").map(x=>x.trim()).filter(Boolean);const existing_categories=categoryExistingText.split("\n").map(x=>x.trim()).filter(Boolean);if(niche.length<3||target_audience.length<2){setLoadError("Provide a niche and target audience.");return}if(topic_candidates.length<3||topic_candidates.length>15){setLoadError("Provide three to fifteen topic candidates, one per line.");return}setBusy("Design category taxonomy");setLoadError("");try{const data=await apiFetch<CategoryDesignResult>("/api/research/category-design",{method:"POST",body:JSON.stringify({niche,target_audience,topic_candidates,existing_categories})});setCategoryDesignResult(data);setResult({label:"Design category taxonomy",data:{asset_id:data.asset_id,root_category:data.root_category,category_count:data.category_count,categories_flagged_for_review:data.categories_flagged_for_review,search_volume_validated:data.search_volume_validated,publishing_started:data.publishing_started},time:new Date().toISOString()})}catch(err){setLoadError(err instanceof Error?err.message:"Category taxonomy could not be generated")}finally{setBusy("")}};
