 const createInfographic=async(e:FormEvent)=>{e.preventDefault();const title=infographicTitle.trim();const key_points=infographicPointsText.split("\n").map(x=>x.trim()).filter(Boolean);const source_urls=infographicSourceUrls.split("\n").map(x=>x.trim()).filter(Boolean);if(title.length<3){setLoadError("Enter an infographic title of at least three characters.");return}if(key_points.length<3||key_points.length>6){setLoadError("Provide between three and six key points, one per line.");return}if(key_points.some(x=>x.length>220)){setLoadError("Each key point must be at most 220 characters.");return}setBusy("Create SVG infographic");setLoadError("");try{const data=await apiFetch<InfographicResult>("/api/content/infographic",{method:"POST",body:JSON.stringify({title,subtitle:infographicSubtitle.trim(),audience:infographicAudience.trim(),key_points,source_urls})});setInfographicResult(data);setResult({label:"Create SVG infographic",data:{asset_id:data.asset_id,title:data.title,format:data.format,card_count:data.cards.length,requires_review:data.requires_review,publishing_started:data.publishing_started},time:new Date().toISOString()})}catch(err){setLoadError(err instanceof Error?err.message:"Infographic generation failed")}finally{setBusy("")}};
