 const runSkillFinder=async(e:FormEvent)=>{e.preventDefault();const q=skillFinderQuery.trim();if(q.length<2){setLoadError("Enter at least two characters to search the skill inventory.");return}const params=["q="+encodeURIComponent(q),"limit=10"];if(skillFinderStage)params.push("stage="+encodeURIComponent(skillFinderStage));if(skillFinderStatus)params.push("status="+encodeURIComponent(skillFinderStatus));try{await operate("Find matching skills","/api/skills/find?"+params.join("&"),undefined,"GET")}catch{/* Error already rendered. */}};
